function assert_plant_provenance(plant_data, expected_plant)
% assert_plant_provenance  Reject stale SI data for a different VM plant.

arguments
  plant_data struct
  expected_plant virtualMotor.PlantConfig
end

required = ["vm_plant", "vm_mode"];
if ~all(isfield(plant_data, required)) || ...
    isempty(plant_data.vm_plant) || isempty(plant_data.vm_mode)
  error("experiment:exp01:plantProvenanceMismatch", ...
    "plant.mat must be regenerated by exp01 for the current VirtualMotor preset.");
end

actual_plant = virtualMotor.PlantConfig.from_struct(plant_data.vm_plant);
if ~isequaln(actual_plant.to_struct(), expected_plant.to_struct())
  error("experiment:exp01:plantProvenanceMismatch", ...
    "plant.mat VirtualMotor parameters differ from the active preset; rerun exp01.");
end

expected_mode = virtualMotor.torsional_mode(expected_plant);
actual_frequency_hz = double(plant_data.vm_mode.natural_frequency_hz);
actual_damping_ratio = double(plant_data.vm_mode.damping_ratio);
if ~isfinite(actual_frequency_hz) || ~isfinite(actual_damping_ratio) || ...
    abs(actual_frequency_hz - expected_mode.natural_frequency_hz) > 1e-6 || ...
    abs(actual_damping_ratio - expected_mode.damping_ratio) > 1e-9
  error("experiment:exp01:plantProvenanceMismatch", ...
    "plant.mat torsional-mode metadata differs from the active preset; rerun exp01.");
end
end
